import type { Locale } from 'date-fns';
import { format } from 'date-fns';
import { enUS } from 'date-fns/locale';
import { Calendar as CalendarIcon } from 'lucide-react-native';
import { useRef } from 'react';
import { Pressable, View } from 'react-native';

import { cn } from '@/lib/utils';

import { AppBottomSheet, type AppBottomSheetRef } from './bottom-sheet';
import { Calendar, type CalendarLabels } from './calendar';
import { Icon } from './icon';
import { Text } from './text';

export interface DatePickerProps {
  value?: Date;
  onChange: (date: Date) => void;
  placeholder?: string;
  /** date-fns format token for the trigger label (default `PP`, e.g. "Jun 25, 2026"). */
  displayFormat?: string;
  minDate?: Date;
  maxDate?: Date;
  /** date-fns locale for the label + calendar. Pass `useDateFnsLocale()`. */
  locale?: Locale;
  weekStartsOn?: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  /** Calendar accessibility labels (localize via your i18n layer). */
  calendarLabels?: Partial<CalendarLabels>;
  disabled?: boolean;
  error?: boolean;
  className?: string;
}

/** Date field that opens a calendar in a bottom sheet. */
export function DatePicker({
  value,
  onChange,
  placeholder = 'Select a date',
  displayFormat = 'PP',
  minDate,
  maxDate,
  locale = enUS,
  weekStartsOn,
  calendarLabels,
  disabled,
  error,
  className,
}: DatePickerProps) {
  const sheet = useRef<AppBottomSheetRef>(null);
  const label = value ? format(value, displayFormat, { locale }) : placeholder;

  return (
    <>
      <Pressable
        accessibilityRole="button"
        accessibilityState={{ disabled: Boolean(disabled) }}
        accessibilityLabel={label}
        disabled={disabled}
        onPress={() => sheet.current?.present()}
        className={cn(
          'h-12 flex-row items-center justify-between rounded-lg border border-input bg-background px-4',
          error && 'border-destructive',
          disabled && 'opacity-50',
          className,
        )}
      >
        <Text className={cn('flex-1', !value && 'text-muted-foreground')} numberOfLines={1}>
          {label}
        </Text>
        <Icon as={CalendarIcon} size={18} className="text-muted-foreground" />
      </Pressable>

      <AppBottomSheet ref={sheet}>
        <View className="px-4 pt-2">
          <Calendar
            value={value}
            // Open on a month that has selectable days even when value is unset.
            initialMonth={value ?? minDate ?? maxDate}
            minDate={minDate}
            maxDate={maxDate}
            locale={locale}
            weekStartsOn={weekStartsOn}
            labels={calendarLabels}
            onChange={(date) => {
              onChange(date);
              sheet.current?.dismiss();
            }}
          />
        </View>
      </AppBottomSheet>
    </>
  );
}
